// ============================================================================
// ColorEmoteFont 结构实例
// ============================================================================

const ColorEmoteFont colorEmoteFont = {
    colorEmoteEntries,      // map
    colorEmoteBitmapData,   // bitmap_data
    sizeof(colorEmoteEntries) / sizeof(colorEmoteEntries[0])  // count
};

// ============================================================================
// 二分查找彩色 Emote 索引
// ============================================================================
int findColorEmoteIndex(uint16_t compressedCodePoint) {
    if (colorEmoteFont.count == 0) return -1;

    int left = 0;
    int right = colorEmoteFont.count - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;
        uint16_t midCompressed = pgm_read_word(&colorEmoteFont.map[mid]);

        if (midCompressed == compressedCodePoint) {
            return mid;
        } else if (midCompressed < compressedCodePoint) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return -1;  // 未找到
}

